  rw_cells asegs m 0x98e30 [C8 (Z_to_bv 64 AFLAGS)] ->
  rw_cells asegs m 0x9e6a4 [C4 (Z_to_bv 64 0x1000); C4 (Z_to_bv 64 0); C4 (Z_to_bv 64 0xbe)] ->
